.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.3s;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #2ecc71;
    background: #2ecc71;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    min-width: 20px;
    max-width: 60px;
    margin-top: -1.2rem;
}

.step-connector.completed {
    background: #2ecc71;
}

/* Form Styles */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-group textarea {
    min-height: 100px;
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.checkbox-group input[type="checkbox"] {
    width: auto;
}

.checkbox-group label {
    display: inline;
    margin-bottom: 0;
    font-weight: normal;
}

/* Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #444;
}

/* Buttons */
.form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    gap: 1rem;
}

.btn-next,
.btn-submit {
    padding: 0.7rem 2rem;
    background: #4361ee;
    color: #fff;
    border: none;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    margin-left: auto;
    transition: background 0.2s;
}

.btn-next:hover,
.btn-submit:hover {
    background: #3651d4;
}

.btn-next:disabled,
.btn-submit:disabled {
    background: #a0a0a0;
    cursor: not-allowed;
}

.btn-back {
    padding: 0.7rem 2rem;
    background: #fff;
    color: #666;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-back:hover {
    background: #f5f5f5;
}

.btn-add {
    padding: 0.5rem 1.2rem;
    background: transparent;
    color: #4361ee;
    border: 1px dashed #4361ee;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
    transition: background 0.2s;
}

.btn-add:hover {
    background: #f0f4ff;
}

.btn-remove {
    padding: 0.3rem 0.8rem;
    background: transparent;
    color: #e74c3c;
    border: 1px solid #e74c3c;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-remove:hover {
    background: #fdf0ef;
}

.btn-edit {
    padding: 0.3rem 0.8rem;
    background: transparent;
    color: #4361ee;
    border: none;
    font-size: 0.85rem;
    cursor: pointer;
    text-decoration: underline;
}

.btn-edit:hover {
    color: #3651d4;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px !important;
}

.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.3rem;
}

/* Error Message */
.error-message {
    background: #fdf0ef;
    color: #e74c3c;
    padding: 0.8rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    border: 1px solid #f5c6cb;
    font-size: 0.9rem;
}

/* Review Section */
.review-section {
    border: 1px solid #e0e0e0;
